def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    if old == 0:
        return None

    change_ratio = (new - old) / old
    percentage = change_ratio * 100

    return {
        "value": percentage,
        "trace": {
            "old_value": old,
            "new_value": new,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": "percentage",
                "unit": "percentage"
            }
        }
    }
